import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { RUTINA_FORM_FIELDS, OPERACIONAL_FORM_FIELDS, PERSONAL_HORAS_FORM_FIELDS, PERSONAL_VACACIONES_FORM_FIELDS, TECNICO_FORM_FIELDS } from './constants';
import type { FormData, Status, FormField } from './types';
import { submitData } from './services/googleSheetsService';
import Input from './components/Input';
import Button from './components/Button';
import Alert from './components/Alert';
import Textarea from './components/Textarea';
import Select from './components/Select';
import CheckboxGroup from './components/CheckboxGroup';
import { CheckCircleIcon } from './components/icons/CheckCircleIcon';
import { XCircleIcon } from './components/icons/XCircleIcon';
import { CogIcon } from './components/icons/CogIcon';
import { ScriptHelp } from './components/ScriptHelp';

type Workflow = 'rutina' | 'operacional' | 'tecnico' | 'personal' | 'personal_horas' | 'personal_vacaciones';
type Errors = Record<string, string>;
type HistoryItem = {
    [key: string]: string | number | boolean | string[];
    timestamp: string;
    synced: boolean;
};

// --- URLs Config ---
const APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwnFy_KVZQqvSATkFMeGpXUtfQVnJIljE1zm9sN68FWHCs5V5xte3pHy3X4aw1_25Gy/exec';
const GOOGLE_SHEET_URL = 'https://docs.google.com/spreadsheets/d/1oRMEzIffoGoKdsXVNx68tJMPUCLt5pqG9D5v3IfupEs/edit';


const App: React.FC = () => {
    const [workflow, setWorkflow] = useState<Workflow | null>(null);
    const [formData, setFormData] = useState<FormData>({});
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [status, setStatus] = useState<Status>({ type: 'idle', message: '' });
    const [errors, setErrors] = useState<Errors>({});
    const [history, setHistory] = useState<HistoryItem[]>([]);
    const [showScriptHelp, setShowScriptHelp] = useState(false);

    const { currentFields, sheetName, formTitle } = useMemo(() => {
        if (workflow === 'rutina') {
            return {
                currentFields: RUTINA_FORM_FIELDS,
                sheetName: 'Rutina',
                formTitle: 'Registro de Rutina'
            };
        }
        if (workflow === 'operacional') {
            return {
                currentFields: OPERACIONAL_FORM_FIELDS,
                sheetName: 'Operacional',
                formTitle: 'Registro Operacional'
            };
        }
        if (workflow === 'tecnico') {
            return {
                currentFields: TECNICO_FORM_FIELDS,
                sheetName: 'Bombeos',
                formTitle: 'Registro Técnico de Bombeo'
            };
        }
        if (workflow === 'personal_horas') {
            return {
                currentFields: PERSONAL_HORAS_FORM_FIELDS,
                sheetName: 'Registro_horario',
                formTitle: 'Registro de Horas por Período'
            };
        }
        if (workflow === 'personal_vacaciones') {
            return {
                currentFields: PERSONAL_VACACIONES_FORM_FIELDS,
                sheetName: 'Vacaciones',
                formTitle: 'Solicitud de Vacaciones'
            };
        }
        return { currentFields: [], sheetName: '', formTitle: '' };
    }, [workflow]);

    const getInitialState = useCallback((fields: FormField[]): FormData => {
        const today = new Date().toISOString().split('T')[0];
        const now = new Date().toTimeString().split(' ')[0].substring(0, 5);

        const initialState: FormData = {};

        if (workflow === 'rutina' || workflow === 'operacional' || workflow === 'tecnico') {
            initialState['date'] = today;
        }

        if (workflow === 'operacional') {
            initialState['hora'] = now;
        }

        if (workflow === 'personal_horas') {
            initialState['fecha_inicio'] = today;
            initialState['fecha_fin'] = today;
            initialState['hora_inicio'] = '08:00';
            initialState['hora_fin'] = '15:00';
            initialState['nombre'] = []; // Checkbox group
        }

        if (workflow === 'personal_vacaciones') {
            initialState['fecha_inicio'] = today;
            initialState['fecha_fin'] = today;
        }

        fields.forEach(field => {
            if (initialState[field.id] === undefined) {
                if (field.type === 'checkbox-group') {
                    initialState[field.id] = [];
                } else {
                    initialState[field.id] = '';
                }
            }
        });

        return initialState;
    }, [workflow]);

    useEffect(() => {
        if (workflow) {
            setFormData(getInitialState(currentFields));
            setErrors({});
            setStatus({ type: 'idle', message: '' });

            // Cargar historial de localStorage
            const savedHistory = localStorage.getItem(`history_${workflow}`);
            if (savedHistory) {
                try {
                    setHistory(JSON.parse(savedHistory));
                } catch (e) {
                    setHistory([]);
                }
            } else {
                setHistory([]);
            }
        }
    }, [workflow, currentFields, getInitialState]);

    const handleInputChange = (id: string, value: string | number | string[]) => {
        setFormData(prev => ({ ...prev, [id]: value }));
        if (errors[id]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[id];
                return newErrors;
            });
        }
    };

    const validateForm = (): boolean => {
        const newErrors: Errors = {};
        currentFields.forEach(field => {
            if (field.required) {
                const val = formData[field.id];
                if (field.type === 'checkbox-group') {
                   if (!val || (val as string[]).length === 0) {
                       newErrors[field.id] = 'Debes seleccionar al menos una opción.';
                   }
                } else if (!val && val !== 0) {
                    newErrors[field.id] = 'Este campo es obligatorio.';
                }
            }
        });
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!validateForm()) return;

        setIsLoading(true);
        setStatus({ type: 'idle', message: '' });

        try {
            await submitData(formData, APPS_SCRIPT_URL, sheetName, GOOGLE_SHEET_URL);
            setStatus({ type: 'success', message: '¡Datos guardados con éxito en la hoja de cálculo!' });

            // Guardar en historial local
            const newItem: HistoryItem = {
                ...formData,
                timestamp: new Date().toLocaleTimeString(),
                synced: true
            };
            const updatedHistory = [newItem, ...history].slice(0, 10);
            setHistory(updatedHistory);
            localStorage.setItem(`history_${workflow}`, JSON.stringify(updatedHistory));

            // Resetear formulario (manteniendo algunos campos)
            const resetData = getInitialState(currentFields);
            if (workflow === 'rutina' || workflow === 'operacional' || workflow === 'tecnico') {
                resetData['date'] = formData['date'];
            }
            if (workflow === 'rutina' || workflow === 'operacional') {
                resetData['operario'] = formData['operario'];
            }
            setFormData(resetData);

            window.scrollTo({ top: 0, behavior: 'smooth' });
        } catch (error: any) {
            console.error(error);
            setStatus({ type: 'error', message: error.message || 'Error al conectar con Google Sheets.' });
        } finally {
            setIsLoading(false);
        }
    };

    const renderField = (field: FormField) => {
        const commonProps = {
            key: field.id,
            id: field.id,
            label: field.label,
            value: formData[field.id] as any,
            required: field.required,
            className: field.className,
            readOnly: field.readOnly,
        };

        switch (field.type) {
            case 'select':
                return (
                    <Select 
                        {...commonProps} 
                        options={field.options || []} 
                        onChange={(e) => handleInputChange(field.id, e.target.value)}
                    />
                );
            case 'textarea':
                return (
                    <Textarea 
                        {...commonProps} 
                        placeholder={`Introduce ${field.label.toLowerCase()}`}
                        onChange={(e) => handleInputChange(field.id, e.target.value)}
                    />
                );
            case 'checkbox-group':
                return (
                    <CheckboxGroup
                        {...commonProps}
                        options={field.options || []}
                        value={formData[field.id] as string[]}
                        onChange={handleInputChange}
                    />
                );
            case 'number':
                return (
                    <Input 
                        {...commonProps} 
                        type="number" 
                        error={errors[field.id]}
                        onChange={(e) => handleInputChange(field.id, e.target.value)}
                    />
                );
            default:
                return (
                    <Input 
                        {...commonProps} 
                        type={field.type} 
                        error={errors[field.id]}
                        onChange={(e) => handleInputChange(field.id, e.target.value)}
                    />
                );
        }
    };

    if (!workflow) {
        return (
            <div className="min-h-screen p-4 sm:p-8 flex items-center justify-center">
                <div className="max-w-2xl w-full">
                    <div className="text-center mb-10">
                        <div className="inline-block p-4 bg-blue-600 rounded-3xl shadow-lg mb-6">
                            <svg className="w-12 h-12 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </div>
                        <h1 className="text-4xl font-extrabold text-slate-800 dark:text-white mb-2">Registros Aqualia</h1>
                        <p className="text-slate-600 dark:text-slate-400">Selecciona el tipo de registro que deseas realizar</p>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {[
                            { id: 'rutina', title: 'Registro de Rutina', icon: '📝', color: 'bg-blue-500' },
                            { id: 'operacional', title: 'Registro Operacional', icon: '⚡', color: 'bg-amber-500' },
                            { id: 'tecnico', title: 'Técnico Bombeos', icon: '⚙️', color: 'bg-emerald-500' },
                            { id: 'personal', title: 'Personal y Horarios', icon: '👤', color: 'bg-indigo-500' }
                        ].map(item => (
                            <button
                                key={item.id}
                                onClick={() => item.id === 'personal' ? setWorkflow('personal') : setWorkflow(item.id as Workflow)}
                                className="group relative p-6 bg-white dark:bg-slate-800 rounded-2xl shadow-md border border-slate-200 dark:border-slate-700 hover:shadow-xl hover:-translate-y-1 transition-all duration-300 overflow-hidden"
                            >
                                <div className={`absolute top-0 right-0 w-24 h-24 -mr-8 -mt-8 ${item.color} opacity-10 rounded-full group-hover:scale-150 transition-transform duration-500`}></div>
                                <div className="text-4xl mb-4">{item.icon}</div>
                                <h3 className="text-xl font-bold text-slate-800 dark:text-white group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">{item.title}</h3>
                            </button>
                        ))}
                    </div>

                    <div className="mt-8 flex justify-center">
                        <button 
                            onClick={() => setShowScriptHelp(true)}
                            className="flex items-center gap-2 text-sm font-medium text-slate-500 hover:text-blue-600 transition-colors"
                        >
                            <CogIcon className="h-5 w-5" />
                            Ayuda con Google Apps Script
                        </button>
                    </div>

                    {showScriptHelp && (
                        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
                            <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-y-auto p-6 sm:p-10 relative">
                                <button 
                                    onClick={() => setShowScriptHelp(false)}
                                    className="absolute top-4 right-4 p-2 text-slate-400 hover:text-slate-600 dark:hover:text-white transition-colors"
                                >
                                    <XCircleIcon className="h-8 w-8" />
                                </button>
                                <ScriptHelp />
                            </div>
                        </div>
                    )}
                </div>
            </div>
        );
    }

    if (workflow === 'personal') {
        return (
            <div className="min-h-screen p-4 sm:p-8 flex items-center justify-center">
                <div className="max-w-xl w-full">
                    <button 
                        onClick={() => setWorkflow(null)}
                        className="mb-8 flex items-center text-blue-600 font-medium hover:underline"
                    >
                        ← Volver al inicio
                    </button>
                    <h1 className="text-3xl font-bold text-slate-800 dark:text-white mb-6">Gestión de Personal</h1>
                    <div className="space-y-4">
                        <button
                            onClick={() => setWorkflow('personal_horas')}
                            className="w-full p-6 text-left bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 hover:border-blue-500 transition-all flex items-center justify-between group"
                        >
                            <div>
                                <div className="text-2xl mb-1">⏰</div>
                                <div className="text-lg font-bold text-slate-800 dark:text-white">Horas por Período</div>
                                <div className="text-sm text-slate-500">Registrar jornadas, actuaciones y horas extra</div>
                            </div>
                            <div className="text-slate-300 group-hover:text-blue-500 transition-colors text-2xl">→</div>
                        </button>
                        <button
                            onClick={() => setWorkflow('personal_vacaciones')}
                            className="w-full p-6 text-left bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 hover:border-blue-500 transition-all flex items-center justify-between group"
                        >
                            <div>
                                <div className="text-2xl mb-1">🌴</div>
                                <div className="text-lg font-bold text-slate-800 dark:text-white">Vacaciones</div>
                                <div className="text-sm text-slate-500">Solicitud y registro de días de descanso</div>
                            </div>
                            <div className="text-slate-300 group-hover:text-blue-500 transition-colors text-2xl">→</div>
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen py-8 px-4 sm:px-6 lg:px-8">
            <div className="max-w-4xl mx-auto">
                <div className="mb-8 flex items-center justify-between">
                    <button 
                        onClick={() => workflow.startsWith('personal_') ? setWorkflow('personal') : setWorkflow(null)}
                        className="flex items-center text-blue-600 font-bold hover:text-blue-800 transition-colors"
                    >
                        <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" />
                        </svg>
                        Volver
                    </button>
                    <div className="px-4 py-1.5 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 text-xs font-bold uppercase tracking-wider rounded-full border border-blue-200 dark:border-blue-800 shadow-sm">
                        Modo {workflow.replace('_', ' ')}
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-xl overflow-hidden border border-slate-200 dark:border-slate-700 animate-fade-in">
                    <div className="bg-blue-600 dark:bg-blue-700 px-6 py-8 sm:px-10">
                        <h1 className="text-2xl sm:text-3xl font-extrabold text-white">{formTitle}</h1>
                        <p className="mt-2 text-blue-100 text-sm">Completa todos los campos obligatorios para registrar los datos.</p>
                    </div>

                    <form onSubmit={handleSubmit} className="p-6 sm:p-10 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            {(workflow === 'rutina' || workflow === 'operacional' || workflow === 'tecnico') && (
                                <Input
                                    id="date"
                                    label="Fecha"
                                    type="date"
                                    value={formData['date'] as string}
                                    onChange={(e) => handleInputChange('date', e.target.value)}
                                    required
                                />
                            )}
                            {workflow === 'operacional' && (
                                <Input
                                    id="hora"
                                    label="Hora"
                                    type="time"
                                    value={formData['hora'] as string}
                                    onChange={(e) => handleInputChange('hora', e.target.value)}
                                    required
                                />
                            )}
                            {currentFields.map(field => renderField(field))}
                        </div>

                        <div className="pt-6 border-t border-slate-100 dark:border-slate-700 space-y-4">
                            <Alert type={status.type} message={status.message} />

                            <Button type="submit" isLoading={isLoading}>
                                {isLoading ? 'Guardando...' : 'Guardar Registro'}
                            </Button>
                        </div>
                    </form>
                </div>

                {history.length > 0 && (
                    <div className="mt-12 animate-fade-in">
                        <div className="flex items-center justify-between mb-4">
                            <h2 className="text-xl font-bold text-slate-800 dark:text-white">Historial Local</h2>
                            <span className="text-xs font-medium px-2 py-1 bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-400 rounded-md">
                                Este dispositivo
                            </span>
                        </div>
                        <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
                            <div className="overflow-x-auto">
                                <table className="w-full text-left border-collapse">
                                    <thead>
                                        <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                                            <th className="px-4 py-3 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Registro</th>
                                            {workflow === 'rutina' && <th className="px-4 py-3 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Punto</th>}
                                            {(workflow === 'personal_horas' || workflow === 'personal_vacaciones') && (
                                                <th className="px-4 py-3 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Fecha Actividad</th>
                                            )}
                                            {workflow === 'personal_horas' && <th className="px-4 py-3 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Nombre</th>}
                                            {workflow === 'personal_horas' && <th className="px-4 py-3 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Actuación</th>}
                                            {workflow === 'personal_horas' && <th className="px-4 py-3 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider text-center">Horas</th>}
                                            {workflow === 'tecnico' && <th className="px-4 py-3 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Estación</th>}
                                            <th className="px-4 py-3 text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider text-center">Estado</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                        {history.map((item, idx) => (
                                            <tr key={idx} className="hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors">
                                                <td className="px-4 py-3 text-sm text-slate-500 dark:text-slate-400 font-mono">{item.timestamp}</td>
                                                {workflow === 'rutina' && <td className="px-4 py-3 text-sm font-medium text-slate-700 dark:text-slate-300">{item.punto_de_muestreo}</td>}
                                                {(workflow === 'personal_horas' || workflow === 'personal_vacaciones') && (
                                                    <td className="px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-300">{item.fecha_inicio}</td>
                                                )}
                                                {workflow === 'personal_horas' && (
                                                  <td className="px-4 py-3 text-sm text-slate-700 dark:text-slate-300">
                                                    {Array.isArray(item.nombre) ? item.nombre.join(', ') : item.nombre}
                                                  </td>
                                                )}
                                                {workflow === 'personal_horas' && <td className="px-4 py-3 text-sm text-slate-700 dark:text-slate-300 truncate max-w-[150px]">{item.actuacion}</td>}
                                                {workflow === 'personal_horas' && <td className="px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-300 text-center bg-blue-50/50 dark:bg-blue-900/20">{item.horas}</td>}
                                                {workflow === 'tecnico' && <td className="px-4 py-3 text-sm font-medium text-slate-700 dark:text-slate-300">{item.bombeo}</td>}
                                                <td className="px-4 py-3 text-center">
                                                    <div className="flex justify-center">
                                                        <CheckCircleIcon className="h-5 w-5 text-green-500" />
                                                    </div>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                )}

                <footer className="mt-12 text-center text-slate-500 dark:text-slate-400 text-sm">
                    <p>Creado para la recolección eficiente de datos.</p>
                </footer>
            </div>
        </div>
    );
};

export default App;

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { RUTINA_FORM_FIELDS, OPERACIONAL_FORM_FIELDS, PERSONAL_HORAS_FORM_FIELDS, PERSONAL_VACACIONES_FORM_FIELDS, TECNICO_FORM_FIELDS } from './constants';
import type { FormData, Status, FormField } from './types';
import { submitData } from './services/googleSheetsService';
import Input from './components/Input';
import Button from './components/Button';
import Alert from './components/Alert';
import Textarea from './components/Textarea';
import Select from './components/Select';
import CheckboxGroup from './components/CheckboxGroup';
import { CheckCircleIcon } from './components/icons/CheckCircleIcon';
import { XCircleIcon } from './components/icons/XCircleIcon';
import { CogIcon } from './components/icons/CogIcon';
import { ScriptHelp } from './components/ScriptHelp';

type Workflow = 'rutina' | 'operacional' | 'tecnico' | 'personal' | 'personal_horas' | 'personal_vacaciones';
type Errors = Record<string, string>;
type HistoryItem = {
    [key: string]: string | number | boolean | string[];
    timestamp: string;
    synced: boolean;
};

// --- URLs Config ---
const APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwnFy_KVZQqvSATkFMeGpXUtfQVnJIljE1zm9sN68FWHCs5V5xte3pHy3X4aw1_25Gy/exec';
const GOOGLE_SHEET_URL = 'https://docs.google.com/spreadsheets/d/1oRMEzIffoGoKdsXVNx68tJMPUCLt5pqG9D5v3IfupEs/edit';


const App: React.FC = () => {
    const [workflow, setWorkflow] = useState<Workflow | null>(null);
    const [formData, setFormData] = useState<FormData>({});
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [status, setStatus] = useState<Status>({ type: 'idle', message: '' });
    const [errors, setErrors] = useState<Errors>({});
    const [history, setHistory] = useState<HistoryItem[]>([]);
    const [showScriptHelp, setShowScriptHelp] = useState(false);

    const { currentFields, sheetName, formTitle } = useMemo(() => {
        if (workflow === 'rutina') {
            return {
                currentFields: RUTINA_FORM_FIELDS,
                sheetName: 'Rutina',
                formTitle: 'Registro de Rutina'
            };
        }
        if (workflow === 'operacional') {
            return {
                currentFields: OPERACIONAL_FORM_FIELDS,
                sheetName: 'Operacional',
                formTitle: 'Registro Operacional'
            };
        }
        if (workflow === 'tecnico') {
            return {
                currentFields: TECNICO_FORM_FIELDS,
                sheetName: 'Bombeos',
                formTitle: 'Registro Técnico de Bombeo'
            };
        }
        if (workflow === 'personal_horas') {
            return {
                currentFields: PERSONAL_HORAS_FORM_FIELDS,
                sheetName: 'Registro_horario',
                formTitle: 'Registro de Horas por Período'
            };
        }
        if (workflow === 'personal_vacaciones') {
            return {
                currentFields: PERSONAL_VACACIONES_FORM_FIELDS,
                sheetName: 'Vacaciones',
                formTitle: 'Solicitud de Vacaciones'
            };
        }
        return { currentFields: [], sheetName: '', formTitle: '' };
    }, [workflow]);

    const getInitialState = useCallback((fields: FormField[]): FormData => {
        const today = new Date().toISOString().split('T')[0];
        const now = new Date().toTimeString().split(' ')[0].substring(0, 5);

        const initialState: FormData = {};

        if (workflow === 'rutina' || workflow === 'operacional' || workflow === 'tecnico') {
            initialState['date'] = today;
        }

        if (workflow === 'operacional') {
            initialState['hora'] = now;
        }

        if (workflow === 'personal_horas') {
            initialState['fecha_inicio'] = today;
            initialState['fecha_fin'] = today;
            initialState['hora_inicio'] = '08:00';
            initialState['hora_fin'] = '15:00';
            initialState['nombre'] = []; // Checkbox group
        }

        if (workflow === 'personal_vacaciones') {
            initialState['fecha_inicio'] = today;
            initialState['fecha_fin'] = today;
        }

        fields.forEach(field => {
            if (initialState[field.id] === undefined) {
                if (field.type === 'checkbox-group') {
                    initialState[field.id] = [];
                } else {
                    initialState[field.id] = '';
                }
            }
        });

        return initialState;
    }, [workflow]);

    useEffect(() => {
        if (workflow) {
            setFormData(getInitialState(currentFields));
            setErrors({});
            setStatus({ type: 'idle', message: '' });

            // Cargar historial de localStorage
            const savedHistory = localStorage.getItem(`history_${workflow}`);
            if (savedHistory) {
                try {
                    setHistory(JSON.parse(savedHistory));
                } catch (e) {
                    setHistory([]);
                }
            } else {
                setHistory([]);
            }
        }
    }, [workflow, currentFields, getInitialState]);

    const handleInputChange = (id: string, value: string | number | string[]) => {
        setFormData(prev => ({ ...prev, [id]: value }));
        if (errors[id]) {
            setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[id];
                return newErrors;
            });
        }
    };

    const validateForm = (): boolean => {
        const newErrors: Errors = {};
        currentFields.forEach(field => {
            if (field.required) {
                const val = formData[field.id];
                if (field.type === 'checkbox-group') {
                   if (!val || (val as string[]).length === 0) {
                       newErrors[field.id] = 'Debes seleccionar al menos una opción.';
                   }
                } else if (!val && val !== 0) {
                    newErrors[field.id] = 'Este campo es obligatorio.';
                }
            }
        });
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!validateForm()) return;

        setIsLoading(true);
        setStatus({ type: 'idle', message: '' });

        try {
            await submitData(formData, APPS_SCRIPT_URL, sheetName, GOOGLE_SHEET_URL);
            setStatus({ type: 'success', message: '¡Datos guardados con éxito en la hoja de cálculo!' });

            // Guardar en historial local
            const newItem: HistoryItem = {
                ...formData,
                timestamp: new Date().toLocaleTimeString(),
                synced: true
            };
            const updatedHistory = [newItem, ...history].slice(0, 10);
            setHistory(updatedHistory);
            localStorage.setItem(`history_${workflow}`, JSON.stringify(updatedHistory));

            // Resetear formulario (manteniendo algunos campos)
            const resetData = getInitialState(currentFields);
            if (workflow === 'rutina' || workflow === 'operacional' || workflow === 'tecnico') {
                resetData['date'] = formData['date'];
            }
            if (workflow === 'rutina' || workflow === 'operacional') {
                resetData['operario'] = formData['operario'];
            }
            setFormData(resetData);

            window.scrollTo({ top: 0, behavior: 'smooth' });
        } catch (error: any) {
            console.error(error);
            setStatus({ type: 'error', message: error.message || 'Error al conectar con Google Sheets.' });
        } finally {
            setIsLoading(false);
        }
    };

    const renderField = (field: FormField) => {
        const commonProps = {
            key: field.id,
            id: field.id,
            label: field.label,
            value: formData[field.id] as any,
            required: field.required,
            className: field.className,
            readOnly: field.readOnly,
        };

        switch (field.type) {
            case 'select':
                return (
                    <Select 
                        {...commonProps} 
                        options={field.options || []} 
                        onChange={(e) => handleInputChange(field.id, e.target.value)}
                    />
                );
            case 'textarea':
                return (
                    <Textarea 
                        {...commonProps} 
                        placeholder={`Introduce ${field.label.toLowerCase()}`}
                        onChange={(e) => handleInputChange(field.id, e.target.value)}
                    />
                );
            case 'checkbox-group':
                return (
                    <CheckboxGroup
                        {...commonProps}
                        options={field.options || []}
                        value={formData[field.id] as string[]}
                        onChange={handleInputChange}
                    />
                );
            case 'number':
                return (
                    <Input 
                        {...commonProps} 
                        type="number" 
                        error={errors[field.id]}
                        onChange={(e) => handleInputChange(field.id, e.target.value)}
                    />
                );
            default:
                return (
                    <Input 
                        {...commonProps} 
                        type={field.type} 
                        error={errors[field.id]}
                        onChange={(e) => handleInputChange(field.id, e.target.value)}
                    />
                );
        }
    };

    if (!workflow) {
        return (
            <div className="min-h-screen p-4 sm:p-8 flex items-center justify-center">
                <div className="max-w-2xl w-full">
                    <div className="text-center mb-10">
                        <div className="inline-block p-4 bg-blue-600 rounded-3xl shadow-lg mb-6">
                            <svg className="w-12 h-12 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" />
                            </svg>
                        </div>
                        <h1 className="text-4xl font-extrabold text-slate-900 dark:text-white mb-4">Sistema de Registros</h1>
                        <p className="text-slate-600 dark:text-slate-400 text-lg">Selecciona el tipo de registro que deseas realizar</p>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <button onClick={() => setWorkflow('rutina')} className="p-6 bg-white dark:bg-slate-800 rounded-2xl shadow-md hover:shadow-xl transition-all border border-slate-200 dark:border-slate-700 text-left group">
                            <h3 className="text-xl font-bold text-slate-800 dark:text-white group-hover:text-blue-600 transition-colors">Registro de Rutina</h3>
                            <p className="text-slate-500 mt-2">Control de turbidez, pH y cloro en puntos de muestreo.</p>
                        </button>
                        <button onClick={() => setWorkflow('operacional')} className="p-6 bg-white dark:bg-slate-800 rounded-2xl shadow-md hover:shadow-xl transition-all border border-slate-200 dark:border-slate-700 text-left group">
                            <h3 className="text-xl font-bold text-slate-800 dark:text-white group-hover:text-blue-600 transition-colors">Registro Operacional</h3>
                            <p className="text-slate-500 mt-2">Seguimiento operacional de parámetros básicos.</p>
                        </button>
                        <button onClick={() => setWorkflow('tecnico')} className="p-6 bg-white dark:bg-slate-800 rounded-2xl shadow-md hover:shadow-xl transition-all border border-slate-200 dark:border-slate-700 text-left group">
                            <h3 className="text-xl font-bold text-slate-800 dark:text-white group-hover:text-blue-600 transition-colors">Bombeos</h3>
                            <p className="text-slate-500 mt-2">Registro técnico de horas y totales de estaciones de bombeo.</p>
                        </button>
                        <button onClick={() => setWorkflow('personal_horas')} className="p-6 bg-white dark:bg-slate-800 rounded-2xl shadow-md hover:shadow-xl transition-all border border-slate-200 dark:border-slate-700 text-left group">
                            <h3 className="text-xl font-bold text-slate-800 dark:text-white group-hover:text-blue-600 transition-colors">Horas Personal</h3>
                            <p className="text-slate-500 mt-2">Registro de actuaciones y horas por operario.</p>
                        </button>
                        <button onClick={() => setWorkflow('personal_vacaciones')} className="p-6 bg-white dark:bg-slate-800 rounded-2xl shadow-md hover:shadow-xl transition-all border border-slate-200 dark:border-slate-700 text-left group">
                            <h3 className="text-xl font-bold text-slate-800 dark:text-white group-hover:text-blue-600 transition-colors">Vacaciones</h3>
                            <p className="text-slate-500 mt-2">Solicitud de días de descanso para el personal.</p>
                        </button>
                    </div>

                    <div className="mt-8 text-center">
                        <button 
                            onClick={() => setShowScriptHelp(!showScriptHelp)}
                            className="inline-flex items-center text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200 text-sm font-medium transition-colors"
                        >
                            <CogIcon className="w-4 h-4 mr-2" />
                            {showScriptHelp ? 'Ocultar configuración de script' : 'Mostrar configuración de script'}
                        </button>
                    </div>

                    {showScriptHelp && (
                        <div className="mt-8 bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-lg border border-slate-200 dark:border-slate-700">
                            <ScriptHelp />
                        </div>
                    )}
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-slate-50 dark:bg-slate-900 py-8 px-4 sm:px-6 lg:px-8 transition-colors duration-300">
            <div className="max-w-4xl mx-auto">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
                    <button 
                        onClick={() => setWorkflow(null)}
                        className="flex items-center text-slate-600 hover:text-blue-600 dark:text-slate-400 dark:hover:text-blue-400 font-medium transition-colors group"
                    >
                        <svg className="w-5 h-5 mr-2 transform group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                        </svg>
                        Volver al Inicio
                    </button>

                    <h1 className="text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight">
                        {formTitle}
                    </h1>
                </div>

                <div className="bg-white dark:bg-slate-800 shadow-2xl rounded-3xl overflow-hidden border border-slate-200 dark:border-slate-700">
                    <div className="p-6 sm:p-10">
                        <Alert type={status.type} message={status.message} />

                        <form onSubmit={handleSubmit} className="mt-8 space-y-8">
                            {/* Campos automáticos si existen */}
                            {(workflow === 'rutina' || workflow === 'operacional' || workflow === 'tecnico') && (
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 p-6 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border border-slate-100 dark:border-slate-700/50">
                                    <Input 
                                        label="Fecha de Registro" 
                                        id="date" 
                                        type="date" 
                                        value={formData['date'] as string} 
                                        onChange={(e) => handleInputChange('date', e.target.value)}
                                        required
                                    />
                                    {workflow === 'operacional' && (
                                        <Input 
                                            label="Hora" 
                                            id="hora" 
                                            type="time" 
                                            value={formData['hora'] as string} 
                                            onChange={(e) => handleInputChange('hora', e.target.value)}
                                            required
                                        />
                                    )}
                                </div>
                            )}

                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                {currentFields.map(renderField)}
                            </div>

                            <div className="pt-6 border-t border-slate-100 dark:border-slate-700">
                                <Button type="submit" isLoading={isLoading}>
                                    {isLoading ? 'Enviando...' : 'Guardar en Google Sheets'}
                                </Button>
                            </div>
                        </form>
                    </div>

                    {/* Historial */}
                    {history.length > 0 && (
                        <div className="bg-slate-50 dark:bg-slate-900/40 px-6 py-8 border-t border-slate-100 dark:border-slate-700">
                            <h2 className="text-lg font-bold text-slate-800 dark:text-white mb-4 flex items-center">
                                <svg className="w-5 h-5 mr-2 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                                </svg>
                                Últimos registros locales ({workflow})
                            </h2>
                            <div className="space-y-3">
                                {history.map((item, idx) => (
                                    <div key={idx} className="flex items-center justify-between p-3 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm text-sm">
                                        <div className="truncate flex-1 mr-4">
                                            <span className="font-semibold text-blue-600 dark:text-blue-400 mr-2">#{history.length - idx}</span>
                                            <span className="text-slate-600 dark:text-slate-300">
                                                {item.punto_de_muestreo || item.bombeo || item.nombre || 'Registro'} - {item.timestamp}
                                            </span>
                                        </div>
                                        {item.synced && (
                                            <span className="flex items-center text-xs font-medium text-green-600 dark:text-green-400 bg-green-50 dark:bg-green-900/30 px-2 py-1 rounded-full">
                                                <CheckCircleIcon className="w-3 h-3 mr-1" /> Sincronizado
                                            </span>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                <div className="mt-8 text-center text-slate-500 text-sm">
                    <p>Enviando datos a: <span className="font-mono text-xs opacity-70 break-all">{APPS_SCRIPT_URL}</span></p>
                </div>
            </div>
        </div>
    );
};

