                        </button>
                        <button onClick={() => setWorkflow('personal_vacaciones')} className="w-full p-6 text-left bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 hover:border-blue-500 transition-all flex items-center justify-between group">
