                            <div className="text-slate-300 group-hover:text-blue-500 transition-colors text-2xl">→</div>
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen py-8 px-4 sm:px-6 lg:px-8">
            <div className="max-w-4xl mx-auto">
                <div className="mb-8 flex items-center justify-between">
                    <button onClick={() => workflow.startsWith('personal_') ? setWorkflow('personal') : setWorkflow(null)} className="flex items-center text-blue-600 font-bold hover:text-blue-800">
                        <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg> Volver
