                </div>

                <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-xl border border-slate-200 dark:border-slate-700 overflow-hidden">
                    <div className="bg-blue-600 dark:bg-blue-700 px-6 py-8"><h1 className="text-2xl font-bold text-white">{formTitle}</h1></div>
                    <form onSubmit={handleSubmit} className="p-6 sm:p-10 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            {(workflow === 'rutina' || workflow === 'operacional' || workflow === 'tecnico') && (
                                <Input id="date" label="Fecha" type="date" value={formData['date'] as string} onChange={(e) => handleInputChange('date', e.target.value)} required />
                            )}
