                            {currentFields.map(renderField)}
                        </div>
                        <div className="pt-6 border-t border-slate-100 dark:border-slate-700 space-y-4">
                            <Alert type={status.type} message={status.message} />
                            <Button type="submit" isLoading={isLoading}>{isLoading ? 'Guardando...' : 'Guardar Registro'}</Button>
                        </div>
                    </form>
                </div>

                {history.length > 0 && (
                    <div className="mt-12">
                        <h2 className="text-xl font-bold text-slate-800 dark:text-white mb-4">Historial Local</h2>
                        <div className="bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-x-auto">
                            <table className="w-full text-left border-collapse">
                                <thead>
                                    <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                                        <th className="px-4 py-3 text-xs font-semibold text-slate-500 uppercase">Hora Registro</th>
                                        <th className="px-4 py-3 text-xs font-semibold text-slate-500 uppercase">Resumen</th>
                                        <th className="px-4 py-3 text-xs font-semibold text-slate-500 uppercase text-center">Estado</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                                    {history.map((item, idx) => (
                                        <tr key={idx} className="hover:bg-slate-50 dark:hover:bg-slate-700/50">
                                            <td className="px-4 py-3 text-sm text-slate-500">{item.timestamp}</td>
                                            <td className="px-4 py-3 text-sm font-medium text-slate-700 dark:text-slate-300">
                                                {item.punto_de_muestreo || item.bombeo || item.nombre || 'Registro'}
                                            </td>
                                            <td className="px-4 py-3 text-center"><CheckCircleIcon className="h-5 w-5 text-green-500 mx-auto" /></td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

