import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { RUTINA_FORM_FIELDS, OPERACIONAL_FORM_FIELDS, PERSONAL_HORAS_FORM_FIELDS, PERSONAL_VACACIONES_FORM_FIELDS, TECNICO_FORM_FIELDS } from './constants';
import type { FormData, Status, FormField } from './types';
import { submitData } from './services/googleSheetsService';
import Input from './components/Input';
import Button from './components/Button';
import Alert from './components/Alert';
import Textarea from './components/Textarea';
import Select from './components/Select';
import CheckboxGroup from './components/CheckboxGroup';
import { CheckCircleIcon } from './components/icons/CheckCircleIcon';
import { XCircleIcon } from './components/icons/XCircleIcon';
import { CogIcon } from './components/icons/CogIcon';
import { ScriptHelp } from './components/ScriptHelp';

type Workflow = 'rutina' | 'operacional' | 'tecnico' | 'personal' | 'personal_horas' | 'personal_vacaciones';
type Errors = Record<string, string>;
type HistoryItem = {
    [key: string]: string | number | boolean | string[];
    timestamp: string;
    synced: boolean;
};

const APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwnFy_KVZQqvSATkFMeGpXUtfQVnJIljE1zm9sN68FWHCs5V5xte3pHy3X4aw1_25Gy/exec';
const GOOGLE_SHEET_URL = 'https://docs.google.com/spreadsheets/d/1oRMEzIffoGoKdsXVNx68tJMPUCLt5pqG9D5v3IfupEs/edit';

const App: React.FC = () => {
    const [workflow, setWorkflow] = useState<Workflow | null>(null);
    const [formData, setFormData] = useState<FormData>({});
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [status, setStatus] = useState<Status>({ type: 'idle', message: '' });
    const [errors, setErrors] = useState<Errors>({});
    const [history, setHistory] = useState<HistoryItem[]>([]);
    const [showScriptHelp, setShowScriptHelp] = useState(false);

    const { currentFields, sheetName, formTitle } = useMemo(() => {
        if (workflow === 'rutina') return { currentFields: RUTINA_FORM_FIELDS, sheetName: 'Rutina', formTitle: 'Registro de Rutina' };
        if (workflow === 'operacional') return { currentFields: OPERACIONAL_FORM_FIELDS, sheetName: 'Operacional', formTitle: 'Registro Operacional' };
        if (workflow === 'tecnico') return { currentFields: TECNICO_FORM_FIELDS, sheetName: 'Bombeos', formTitle: 'Registro Técnico de Bombeo' };
        if (workflow === 'personal_horas') return { currentFields: PERSONAL_HORAS_FORM_FIELDS, sheetName: 'Registro_horario', formTitle: 'Registro de Horas por Período' };
        if (workflow === 'personal_vacaciones') return { currentFields: PERSONAL_VACACIONES_FORM_FIELDS, sheetName: 'Vacaciones', formTitle: 'Solicitud de Vacaciones' };
        return { currentFields: [], sheetName: '', formTitle: '' };
    }, [workflow]);

    const getInitialState = useCallback((fields: FormField[]): FormData => {
        const today = new Date().toISOString().split('T')[0];
        const now = new Date().toTimeString().split(' ')[0].substring(0, 5);
        const initialState: FormData = {};

        if (['rutina', 'operacional', 'tecnico'].includes(workflow || '')) {
            initialState['date'] = today;
        }
        if (workflow === 'operacional') initialState['hora'] = now;
        if (workflow === 'personal_horas') {
            initialState['fecha_inicio'] = today;
            initialState['fecha_fin'] = today;
            initialState['hora_inicio'] = '08:00';
            initialState['hora_fin'] = '15:00';
            initialState['nombre'] = [];
        }
        if (workflow === 'personal_vacaciones') {
            initialState['fecha_inicio'] = today;
            initialState['fecha_fin'] = today;
        }

        fields.forEach(field => {
            if (initialState[field.id] === undefined) {
                initialState[field.id] = field.type === 'checkbox-group' ? [] : '';
            }
        });
        return initialState;
    }, [workflow]);

    useEffect(() => {
        if (workflow) {
            setFormData(getInitialState(currentFields));
            setErrors({});
            setStatus({ type: 'idle', message: '' });
            const savedHistory = localStorage.getItem(`history_${workflow}`);
            if (savedHistory) {
                try { setHistory(JSON.parse(savedHistory)); } catch (e) { setHistory([]); }
            } else { setHistory([]); }
        }
    }, [workflow, currentFields, getInitialState]);

    const handleInputChange = (id: string, value: string | number | string[]) => {
        setFormData(prev => ({ ...prev, [id]: value }));
        if (errors[id]) setErrors(prev => {
            const newErrors = { ...prev };
            delete newErrors[id];
            return newErrors;
        });
    };

    const validateForm = (): boolean => {
        const newErrors: Errors = {};
        currentFields.forEach(field => {
            if (field.required) {
                const val = formData[field.id];
                if (field.type === 'checkbox-group') {
                   if (!val || (val as string[]).length === 0) newErrors[field.id] = 'Selecciona al menos una opción.';
                } else if (!val && val !== 0) {
                    newErrors[field.id] = 'Este campo es obligatorio.';
                }
            }
        });
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!validateForm()) return;
        setIsLoading(true);
        setStatus({ type: 'idle', message: '' });

        try {
            await submitData(formData, APPS_SCRIPT_URL, sheetName, GOOGLE_SHEET_URL);
            setStatus({ type: 'success', message: '¡Datos guardados con éxito!' });
            const newItem: HistoryItem = { ...formData, timestamp: new Date().toLocaleTimeString(), synced: true };
            const updatedHistory = [newItem, ...history].slice(0, 10);
            setHistory(updatedHistory);
            localStorage.setItem(`history_${workflow}`, JSON.stringify(updatedHistory));
            const resetData = getInitialState(currentFields);
            if (['rutina', 'operacional', 'tecnico'].includes(workflow || '')) resetData['date'] = formData['date'];
            if (['rutina', 'operacional'].includes(workflow || '')) resetData['operario'] = formData['operario'];
            setFormData(resetData);
            window.scrollTo({ top: 0, behavior: 'smooth' });
        } catch (error: any) {
            setStatus({ type: 'error', message: error.message || 'Error al conectar con Google Sheets.' });
        } finally {
            setIsLoading(false);
        }
    };

    const renderField = (field: FormField) => {
        const commonProps = { key: field.id, id: field.id, label: field.label, value: formData[field.id] as any, required: field.required, className: field.className, readOnly: field.readOnly };
        if (field.type === 'select') return <Select {...commonProps} options={field.options || []} onChange={(e) => handleInputChange(field.id, e.target.value)} />;
        if (field.type === 'textarea') return <Textarea {...commonProps} placeholder={`Introduce ${field.label.toLowerCase()}`} onChange={(e) => handleInputChange(field.id, e.target.value)} />;
        if (field.type === 'checkbox-group') return <CheckboxGroup {...commonProps} options={field.options || []} value={formData[field.id] as string[]} onChange={handleInputChange} />;
        return <Input {...commonProps} type={field.type} error={errors[field.id]} onChange={(e) => handleInputChange(field.id, e.target.value)} />;
    };

    if (!workflow) {
        return (
            <div className="min-h-screen p-4 sm:p-8 flex items-center justify-center">
                <div className="max-w-2xl w-full">
                    <div className="text-center mb-10">
                        <div className="inline-block p-4 bg-blue-600 rounded-3xl shadow-lg mb-6">
                            <svg className="w-12 h-12 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </div>
                        <h1 className="text-4xl font-extrabold text-slate-800 dark:text-white mb-2">Registros Aqualia</h1>
                        <p className="text-slate-600 dark:text-slate-400">Selecciona el tipo de registro que deseas realizar</p>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {[
                            { id: 'rutina', title: 'Registro de Rutina', icon: '📝', color: 'bg-blue-500' },
                            { id: 'operacional', title: 'Registro Operacional', icon: '⚡', color: 'bg-amber-500' },
                            { id: 'tecnico', title: 'Técnico Bombeos', icon: '⚙️', color: 'bg-emerald-500' },
                            { id: 'personal', title: 'Personal y Horarios', icon: '👤', color: 'bg-indigo-500' }
                        ].map(item => (
                            <button
                                key={item.id}
                                onClick={() => item.id === 'personal' ? setWorkflow('personal') : setWorkflow(item.id as Workflow)}
                                className="group relative p-6 bg-white dark:bg-slate-800 rounded-2xl shadow-md border border-slate-200 dark:border-slate-700 hover:shadow-xl hover:-translate-y-1 transition-all duration-300 overflow-hidden text-left"
                            >
                                <div className={`absolute top-0 right-0 w-24 h-24 -mr-8 -mt-8 ${item.color} opacity-10 rounded-full group-hover:scale-150 transition-transform duration-500`}></div>
                                <div className="text-4xl mb-4">{item.icon}</div>
                                <h3 className="text-xl font-bold text-slate-800 dark:text-white group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">{item.title}</h3>
                                <p className="text-sm text-slate-500 mt-2 line-clamp-2">
                                    {item.id === 'rutina' && 'Control de turbidez, pH y cloro en puntos de muestreo.'}
                                    {item.id === 'operacional' && 'Seguimiento operacional de parámetros básicos.'}
                                    {item.id === 'tecnico' && 'Registro de horas y totales de estaciones.'}
                                    {item.id === 'personal' && 'Gestión de horas de operarios y vacaciones.'}
                                </p>
                            </button>
                        ))}
                    </div>

                    <div className="mt-8 flex justify-center">
                        <button onClick={() => setShowScriptHelp(!showScriptHelp)} className="flex items-center gap-2 text-sm font-medium text-slate-500 hover:text-blue-600 transition-colors">
                            <CogIcon className="h-5 w-5" /> Configuración de Script
                        </button>
                    </div>
                    {showScriptHelp && <div className="mt-8"><ScriptHelp /></div>}
                </div>
            </div>
        );
    }

    if (workflow === 'personal') {
        return (
            <div className="min-h-screen p-4 sm:p-8 flex items-center justify-center">
                <div className="max-w-xl w-full">
                    <button onClick={() => setWorkflow(null)} className="mb-8 flex items-center text-blue-600 font-medium hover:underline">← Volver al inicio</button>
                    <h1 className="text-3xl font-bold text-slate-800 dark:text-white mb-6">Gestión de Personal</h1>
                    <div className="space-y-4">
                        <button onClick={() => setWorkflow('personal_horas')} className="w-full p-6 text-left bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 hover:border-blue-500 transition-all flex items-center justify-between group">
                            <div>
                                <div className="text-2xl mb-1">⏰</div>
                                <div className="text-lg font-bold text-slate-800 dark:text-white">Horas por Período</div>
                                <div className="text-sm text-slate-500">Registrar jornadas y actuaciones de operarios</div>
                            </div>
                            <div className="text-slate-300 group-hover:text-blue-500 transition-colors text-2xl">→</div>
                        </button>
                        <button onClick={() => setWorkflow('personal_vacaciones')} className="w-full p-6 text-left bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 hover:border-blue-500 transition-all flex items-center justify-between group">
                            <div>
                                <div className="text-2xl mb-1">🌴</div>
                                <div className="text-lg font-bold text-slate-800 dark:text-white">Vacaciones</div>
                                <div className="text-sm text-slate-500">Solicitud de días de descanso</div>
                            </div>
                            <div className="text-slate-300 group-hover:text-blue-500 transition-colors text-2xl">→</div>
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen py-8 px-4 sm:px-6 lg:px-8 bg-slate-50 dark:bg-slate-900 transition-colors duration-300">
            <div className="max-w-4xl mx-auto">
                <div className="mb-8 flex items-center justify-between">
                    <button onClick={() => workflow.startsWith('personal_') ? setWorkflow('personal') : setWorkflow(null)} className="flex items-center text-blue-600 font-bold hover:text-blue-800 transition-colors">
                        <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg> Volver
                    </button>
                    <div className="px-4 py-1.5 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 text-xs font-bold uppercase rounded-full border border-blue-200 dark:border-blue-800 shadow-sm">Modo {workflow.replace('_', ' ')}</div>
                </div>

                <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-xl border border-slate-200 dark:border-slate-700 overflow-hidden">
                    <div className="bg-blue-600 dark:bg-blue-700 px-6 py-8"><h1 className="text-2xl sm:text-3xl font-bold text-white tracking-tight">{formTitle}</h1></div>
                    <form onSubmit={handleSubmit} className="p-6 sm:p-10 space-y-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            {(workflow === 'rutina' || workflow === 'operacional' || workflow === 'tecnico') && (
                                <Input id="date" label="Fecha" type="date" value={formData['date'] as string} onChange={(e) => handleInputChange('date', e.target.value)} required />
                            )}
                            {workflow === 'operacional' && <Input id="hora" label="Hora" type="time" value={formData['hora'] as string} onChange={(e) => handleInputChange('hora', e.target.value)} required />}
                            {currentFields.map(renderField)}
                        </div>
                        <div className="pt-6 border-t border-slate-100 dark:border-slate-700 space-y-4">
