function doPost(e) {
  try {
    // 1. Verificar si llegan datos
    if (!e.postData || !e.postData.contents) {
      throw new Error("No se recibieron datos (postData).");
    }

    // 2. Leer los datos enviados desde la web
    var data = JSON.parse(e.postData.contents);
    var sheetName = data.sheetName;
    var googleSheetUrl = data.googleSheetUrl;

    if (!googleSheetUrl) throw new Error("URL de Google Sheet no recibida.");
    if (!sheetName) throw new Error("Nombre de la hoja (sheetName) no recibido.");

    // 3. Abrir la hoja de cálculo por URL
    var spreadsheet = SpreadsheetApp.openByUrl(googleSheetUrl);
    var sheet = spreadsheet.getSheetByName(sheetName);

    if (!sheet) {
      throw new Error('No se pudo encontrar la hoja "' + sheetName + '". Verifica el nombre.');
    }

    // 4. Preparar la fila nueva según la hoja seleccionada
    var newRow = [];
    var timestamp = new Date();

    if (sheetName === 'Rutina') {
      newRow = [
        data.date || '',
        data.punto_de_muestreo || '',
        data.turbidez || '',
        data.ph || '',
        data.cloro || '',
        data.color || '',
        data.olor || '',
        data.sabor || '',
        data.operario || '',
        data.observaciones || ''
      ];

    } else if (sheetName === 'Operacional') {
      // ORDEN: Fecha | Hora | pH | Turbidez Bruta | Turbidez Salida | Cloro | Operario | Observaciones
      newRow = [
        data.date || '',
        data.hora || '',
        data.ph || '',
        data.turbidez_bruta || '',   // ← Columna D nueva
        data.turbidez_salida || '',  // ← Antes era "turbidez", ahora renombrada
        data.cloro || '',
        data.operario || '',
        data.observaciones || ''
      ];

    } else if (sheetName === 'Bombeos') {
      newRow = [
        data.date || '',
        data.bombeo || '',
        data.total_bomba_1 || '',
        data.horas_bomba_1 || '',
        data.total_bomba_2 || '',
        data.horas_bomba_2 || '',
        data.observaciones || ''
      ];

    } else if (sheetName === 'Registro_horario') {
      newRow = [
        data.fecha_inicio || '',
        data.fecha_fin || '',
        data.hora_inicio || '',
        data.hora_fin || '',
        data.actuacion || '',
        data.horas || '',
        data.nombre || '',
        data.observaciones || '',
        timestamp
      ];

    } else if (sheetName === 'Vacaciones') {
      newRow = [
        data.nombre || '',
        data.apellidos || '',
        data.fecha_inicio || '',
        data.fecha_fin || '',
        data.dias || '',
        timestamp
      ];

    } else {
      throw new Error('La hoja "' + sheetName + '" no está configurada.');
    }

    // 5. Añadir la fila
    sheet.appendRow(newRow);

    // 6. Responder éxito
    return ContentService
      .createTextOutput(JSON.stringify({
        status: 'success',
        message: '¡Datos guardados con éxito!'
      }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService
      .createTextOutput(JSON.stringify({
        status: 'error',
        message: 'Error: ' + error.toString()
      }))
      .setMimeType(ContentService.MimeType.JSON);
  }
} 
